#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""
matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <cuda_pipeline_primitives.h>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define MATVEC_CP_ASYNC 1
#else
#define MATVEC_CP_ASYNC 0
#endif
#include <cute/tensor.hpp>
using namespace cute;
// C[m] = sum_k A[m,k] * B[k]
// A: (M,K) row-major contiguous, B: (K,) contiguous, C: (M,)
// Skinny-N GEMV specialization: N=1 stays in registers, one output row per
// CTA, and the very large K reduction is split across a small fixed number
// of CTAs. Each CTA streams one contiguous A row-chunk with coalesced
// vectorized evict-first loads; B slices are tiny and are reused through L2
// via read-only cached loads. K partials are reduced by warp shuffles plus
// one small shared-memory cross-warp reduction, then combined across the
// few K slices with a tiny atomicAdd on the single output element.
template <int BlockSize>
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K)
{
  constexpr int NumWarps = BlockSize / 32;
  static_assert(BlockSize % 32 == 0);
  static_assert(NumWarps <= 32);
  const int row  = blockIdx.x;
  if (row >= M) return;
  const int splits = gridDim.y;
  const int chunk = (K + splits - 1) / splits;
  const int64_t kBegin64 = (int64_t)blockIdx.y * (int64_t)chunk;
  if (kBegin64 >= (int64_t)K) return;
  const int kBegin = (int)kBegin64;
  int kEnd = kBegin + chunk;
  if (kEnd > K) kEnd = K;
  const int tid  = threadIdx.x;
  const int lane = tid & 31;
  const int wid  = tid >> 5;
  const float* aRow = A + (int64_t)row * (int64_t)K;
  float acc0 = 0.0f, acc1 = 0.0f, acc2 = 0.0f, acc3 = 0.0f;
  const bool vecOk = ((K & 3) == 0) && ((kBegin & 3) == 0) &&
                     ((reinterpret_cast<uintptr_t>(A) & 0xF) == 0) &&
                     ((reinterpret_cast<uintptr_t>(B) & 0xF) == 0);
  if (vecOk) {
    const int Ks = kEnd - kBegin;
    const int Kv = Ks >> 2;
    const float4* aVec = reinterpret_cast<const float4*>(aRow + kBegin);
    const float4* bVec = reinterpret_cast<const float4*>(B + kBegin);
    int i = tid;
    for (; i + 3 * BlockSize < Kv; i += 4 * BlockSize) {
      const float4 a0 = __ldcs(aVec + i);
      const float4 a1 = __ldcs(aVec + i + BlockSize);
      const float4 a2 = __ldcs(aVec + i + 2 * BlockSize);
      const float4 a3 = __ldcs(aVec + i + 3 * BlockSize);
      const float4 b0 = __ldg(bVec + i);
      const float4 b1 = __ldg(bVec + i + BlockSize);
      const float4 b2 = __ldg(bVec + i + 2 * BlockSize);
      const float4 b3 = __ldg(bVec + i + 3 * BlockSize);
      acc0 = fmaf(a0.x, b0.x, fmaf(a0.y, b0.y, fmaf(a0.z, b0.z, fmaf(a0.w, b0.w, acc0))));
      acc1 = fmaf(a1.x, b1.x, fmaf(a1.y, b1.y, fmaf(a1.z, b1.z, fmaf(a1.w, b1.w, acc1))));
      acc2 = fmaf(a2.x, b2.x, fmaf(a2.y, b2.y, fmaf(a2.z, b2.z, fmaf(a2.w, b2.w, acc2))));
      acc3 = fmaf(a3.x, b3.x, fmaf(a3.y, b3.y, fmaf(a3.z, b3.z, fmaf(a3.w, b3.w, acc3))));
    }
    for (; i < Kv; i += BlockSize) {
      const float4 a = __ldcs(aVec + i);
      const float4 b = __ldg(bVec + i);
      acc0 = fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, fmaf(a.w, b.w, acc0))));
    }
    for (int k = kBegin + (Kv << 2); k < kEnd; ++k)
      acc0 = fmaf(__ldcs(aRow + k), __ldg(B + k), acc0);
  } else {
    for (int k = kBegin + tid; k < kEnd; k += BlockSize)
      acc0 = fmaf(__ldcs(aRow + k), __ldg(B + k), acc0);
  }
  float v = (acc0 + acc1) + (acc2 + acc3);
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1)
    v += __shfl_down_sync(0xffffffffu, v, off);
  __shared__ float warpSums[NumWarps];
  if (lane == 0) warpSums[wid] = v;
  __syncthreads();
  if (wid == 0) {
    float s = (lane < NumWarps) ? warpSums[lane] : 0.0f;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
      s += __shfl_down_sync(0xffffffffu, s, off);
    if (lane == 0) atomicAdd(C + row, s);
  }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A must be (M,K), B must be (K,1)");
  TORCH_CHECK(B.size(1) == 1, "B must have shape (K,1)");
  TORCH_CHECK(A.size(1) == B.size(0), "inner dimensions must match");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  TORCH_CHECK(M > 0 && K > 0, "M and K must be positive");
  TORCH_CHECK(M < (int64_t)INT32_MAX && K < (int64_t)INT32_MAX,
              "M and K must fit in int32");
  auto C = torch::zeros({M, 1}, A_c.options());
  constexpr int BlockSize = 256;
  const int splits = (K >= 262144) ? 8 : 1;
  dim3 grid((unsigned)M, (unsigned)splits);
  dim3 block(BlockSize);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<BlockSize><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)M, (int)K);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ",
              cudaGetErrorString(err));
  return C;
}
